import asyncio, time

@app.get("/async")
async def async_route():
    await asyncio.sleep(2)      # non-blocking: event loop serves others meanwhile
    return {"ok": True}

@app.get("/sync")
def sync_route():
    time.sleep(2)               # blocking, but in a threadpool
    return {"ok": True}

# WRONG: blocks the event loop
import requests

@app.get("/bad")
async def bad_route():
    r = requests.get("https://slow-api.com/data")  # BLOCKS everything
    return r.json()

# RIGHT: use async httpx
import httpx

@app.get("/good")
async def good_route():
    async with httpx.AsyncClient() as client:
        r = await client.get("https://slow-api.com/data")
    return r.json()

# ALSO FINE: use def (runs in threadpool)
@app.get("/also-fine")
def also_fine_route():
    r = requests.get("https://slow-api.com/data")  # OK in threadpool
    return r.json()
